'use strict';
globalThis.SplitAdapt=(()=>{
 let previews=[],selectedFormats=new Set(),signature='';
 const priorEditor=renderEditor;
 function showControls(){$('useBase').disabled=!current();$('previewAdaptation').disabled=!baseComposition||!outputs.some(o=>o.id!==baseComposition.id);}
 renderEditor=function(){priorEditor();showControls();};
 function useBase(){const f=current();if(!f)return;SplitEditor.finishInteraction();checkpoint();baseComposition=SplitAdaptation.capture(f);renderEditor();toast('Composição registrada como formato-base. Abra Adaptar formatos para conferir a prévia.');}
 const stateSignature=()=>JSON.stringify({base:baseComposition,outputs});
 function buildPreviews(){if(!baseComposition)return;signature=stateSignature();previews=outputs.filter(o=>o.id!==baseComposition.id).map(target=>({...SplitAdaptation.adapt(baseComposition,target,{protectManual:$('protectManual').checked}),id:target.id}));$('adaptBaseName').textContent=`${baseComposition.name} · ${baseComposition.w} × ${baseComposition.h} px`;const holder=$('adaptPreviews');holder.replaceChildren();for(const preview of previews){const article=document.createElement('article');article.className='adapt-card';const label=document.createElement('label');label.className='check-field';const input=document.createElement('input');input.type='checkbox';input.checked=selectedFormats.has(preview.id);input.onchange=()=>{input.checked?selectedFormats.add(preview.id):selectedFormats.delete(preview.id);updateApply();};label.append(input,document.createTextNode(`${preview.output.name} · ${preview.output.w} × ${preview.output.h}`));const canvas=document.createElement('canvas');render(canvas,preview.output,false,420);const notice=document.createElement('p');notice.className='hint'+(preview.conflicts?' adaptation-conflict':'');notice.textContent=`${preview.reflow?'Leitura reorganizada':'Relações preservadas'} · ${preview.protectedCount} camada(s) protegida(s)${preview.conflicts?` · ${preview.conflicts} conflito(s): regras ou espaço insuficiente. Revise antes de aplicar.`:''}`;article.append(label,canvas,notice);holder.append(article);}$('acceptAdaptConflicts').checked=false;updateApply();}
 function updateApply(){const selected=previews.filter(p=>selectedFormats.has(p.id)),conflicts=selected.reduce((n,p)=>n+p.conflicts,0);$('adaptSummary').textContent=`${selected.length} formato(s) selecionado(s)${conflicts?` · ${conflicts} conflito(s) sinalizado(s)`:''}`;$('adaptConflictField').hidden=!conflicts;$('applyAdapt').disabled=!selected.length||!!(conflicts&&!$('acceptAdaptConflicts').checked);}
 async function open(){if(!baseComposition){toast('Abra um formato aprovado e escolha Usar como formato-base.');return;}try{await ensureFonts();SplitEditor.finishInteraction();selectedFormats=new Set(outputs.filter(o=>o.id!==baseComposition.id).map(o=>o.id));buildPreviews();$('adaptDialog').showModal();}catch(e){toast(e.message);}}
 function apply(){const chosen=previews.filter(p=>selectedFormats.has(p.id));if(!chosen.length||chosen.some(p=>p.conflicts)&&!$('acceptAdaptConflicts').checked)return false;if(signature!==stateSignature()){buildPreviews();toast('A campanha mudou. Confira a prévia atualizada antes de aplicar.');return false;}checkpoint();const byId=new Map(chosen.map(p=>[p.id,p.output]));outputs=outputs.map(o=>byId.has(o.id)?clone(byId.get(o.id)):o);selectLayer(null);$('adaptDialog').close();refresh();toast(`Composição adaptada em ${chosen.length} formato(s).`,true);return true;}
 $('useBase').onclick=useBase;$('previewAdaptation').onclick=open;$('closeAdapt').onclick=()=>$('adaptDialog').close();$('applyAdapt').onclick=apply;$('protectManual').onchange=buildPreviews;$('acceptAdaptConflicts').onchange=updateApply;$('selectAdaptAll').onclick=()=>{selectedFormats=new Set(previews.map(p=>p.id));buildPreviews();};$('selectAdaptNone').onclick=()=>{selectedFormats.clear();buildPreviews();};
 showControls();
 return{useBase,open,apply,buildPreviews,previews:()=>previews,select:ids=>{selectedFormats=new Set(ids);updateApply();}};
})();
